  (forall i, 0 <= i < n -> cls sp scr (p + i)) -> aacc M p n -> app_rng (rn_ar rn) p n ->
  let fS := Ea0RegionPoisoned.SB + p / 8 in let lS := Ea0RegionPoisoned.SB + (p + n - 1) / 8 in
  art_vis (bhid A model) p n
  /\ (Ea0RegionPoisoned.SB <= fS <= lS /\ lS + 8 <= rn_HI rn)
