  /\ (exists k, Mr0 (Z_to_bv 64 lS) = Some (Z_to_bv 8 k) /\ (k = 0 \/ (p + n - 1) mod 8 < k <= 7))
  /\ (exists w0 w1, rdn ASEGS Mr0 (Z_to_bv 64 (fS - fS mod 8)) 8 = Some w0 /\ rdn ASEGS Mr0 (Z_to_bv 64 (lS - lS mod 8)) 8 = Some w1).
